import { createReadStream } from 'node:fs';
import { appendFile, mkdir, readFile, rename, open, unlink } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { createInterface } from 'node:readline';
import { randomUUID } from 'node:crypto';

async function* lines(path) {
  const stream = createReadStream(path, { encoding: 'utf8' });
  const reader = createInterface({ input: stream, crlfDelay: Infinity });
  try {
    for await (const line of reader) yield line;
  } finally {
    reader.close();
    stream.destroy();
  }
}

function identity(record) {
  if (!record || typeof record !== 'object' || Array.isArray(record) ||
      typeof record.tenant !== 'string' || !record.tenant.length ||
      !Number.isSafeInteger(record.seq)) {
    throw new Error('Event requires a nonempty tenant and an integer seq');
  }
  return JSON.stringify([record.tenant, record.seq]);
}

// Also support pre-existing NDJSON files whose last line has no newline.
async function appendLine(path, line) {
  let prefix = '';
  let file;
  try {
    file = await open(path, 'r');
    const { size } = await file.stat();
    if (size) {
      const last = Buffer.alloc(1);
      await file.read(last, 0, 1, size - 1);
      if (last[0] !== 10) prefix = '\n';
    }
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  } finally {
    await file?.close();
  }
  await appendFile(path, `${prefix}${line}\n`);
}

async function saveCheckpoint(path, nextLine) {
  const temporary = `${path}.${randomUUID()}.tmp`;
  try {
    await appendFile(temporary, `${JSON.stringify({ nextLine })}\n`, { flag: 'wx' });
    await rename(temporary, path);
  } finally {
    await unlink(temporary).catch(error => {
      if (error.code !== 'ENOENT') throw error;
    });
  }
}

export async function processBatch({ inputPath, outputPath, checkpointPath, batchSize = 4 }) {
  if (!Number.isSafeInteger(batchSize) || batchSize <= 0) {
    throw new TypeError('batchSize must be a positive safe integer');
  }
  await mkdir(dirname(outputPath), { recursive: true });
  await mkdir(dirname(checkpointPath), { recursive: true });
  let nextLine = 0;
  let checkpoint;
  try {
    checkpoint = await readFile(checkpointPath, 'utf8');
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  if (checkpoint !== undefined) {
    try {
      const parsed = JSON.parse(checkpoint);
      if (!Number.isSafeInteger(parsed?.nextLine) || parsed.nextLine < 0) {
        throw new Error('Invalid checkpoint');
      }
      nextLine = parsed.nextLine;
    } catch {
      const recovery = join(dirname(checkpointPath), 'recovery');
      await mkdir(recovery, { recursive: true });
      const badPath = join(recovery, 'checkpoint.bad.json');
      // Preserve earlier recovery evidence as well, if present.
      try {
        await rename(badPath, join(recovery, `checkpoint.bad.${randomUUID()}.json`));
      } catch (error) {
        if (error.code !== 'ENOENT') throw error;
      }
      await rename(checkpointPath, badPath);
    }
  }

  const seen = new Set();
  try {
    for await (const line of lines(outputPath)) {
      if (line.trim()) seen.add(identity(JSON.parse(line)));
    }
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }

  const report = { accepted: 0, rejected: 0, duplicates: 0, nextLine };
  let index = 0;
  for await (const line of lines(inputPath)) {
    if (index++ < nextLine) continue;
    let key;
    try {
      key = identity(JSON.parse(line));
    } catch {
      await appendLine(join(dirname(outputPath), 'rejected.ndjson'), line);
      report.rejected++;
      report.nextLine = index;
      continue;
    }
    if (seen.has(key)) {
      report.duplicates++;
    } else {
      await appendLine(outputPath, line);
      seen.add(key);
      report.accepted++;
    }
    report.nextLine = index;
    if (report.accepted === batchSize) break;
  }
  await saveCheckpoint(checkpointPath, report.nextLine);
  return report;
}

// Usage: node bin/ingest.mjs INPUT OUTPUT CHECKPOINT [BATCH_SIZE]
import { processBatch } from '../src/ingest.mjs';

const args = process.argv.slice(2);
if (args.length < 3 || args.length > 4) {
  console.error('Usage: node bin/ingest.mjs INPUT OUTPUT CHECKPOINT [BATCH_SIZE]');
  process.exitCode = 1;
} else {
  const [inputPath, outputPath, checkpointPath, size] = args;
  try {
    const report = await processBatch({
      inputPath, outputPath, checkpointPath,
      ...(size === undefined ? {} : { batchSize: Number(size) }),
    });
    console.log(JSON.stringify(report));
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { processBatch } from '../src/ingest.mjs';

test('default, identity, quarantine, resume and corrupt-checkpoint recovery', async () => {
  const dir = await mkdtemp(join(process.cwd(), '.ingest-test-'));
  try {
    const options = { inputPath: join(dir, 'input'), outputPath: join(dir, 'output'), checkpointPath: join(dir, 'checkpoint') };
    const records = [
      { tenant: 'a', seq: 1, extra: true },
      { tenant: 'b', seq: 1 },
      { tenant: 'a', seq: 2 },
      { tenant: 'a', seq: 3 },
      { tenant: 'a', seq: 4 },
    ];
    const raw = records.map(JSON.stringify);
    await writeFile(options.inputPath, [raw[0], 'broken', '{}', raw[0], ...raw.slice(1)].join('\n'));
    assert.deepEqual(await processBatch(options), { accepted: 4, rejected: 2, duplicates: 1, nextLine: 7 });
    assert.equal(await readFile(join(dir, 'rejected.ndjson'), 'utf8'), 'broken\n{}\n');
    assert.deepEqual(await processBatch({ ...options, batchSize: 1 }), { accepted: 1, rejected: 0, duplicates: 0, nextLine: 8 });
    assert.deepEqual(await processBatch(options), { accepted: 0, rejected: 0, duplicates: 0, nextLine: 8 });
    const output = await readFile(options.outputPath, 'utf8');
    assert.equal(output, raw.join('\n') + '\n');
    await writeFile(options.checkpointPath, 'corrupt');
    assert.deepEqual(await processBatch(options), { accepted: 0, rejected: 2, duplicates: 6, nextLine: 8 });
    assert.equal(await readFile(options.outputPath, 'utf8'), output);
    assert.equal(await readFile(join(dir, 'recovery/checkpoint.bad.json'), 'utf8'), 'corrupt');
    assert.deepEqual(JSON.parse(await readFile(options.checkpointPath, 'utf8')), { nextLine: 8 });
    await assert.rejects(processBatch({ ...options, batchSize: 0 }), /positive/);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

